rules.good:
new ThreadPoolExecutor(8, 16, 60, SECONDS, new LinkedBlockingQueue<>(500),
    new ThreadFactory() {
      private final AtomicInteger n = new AtomicInteger(1);
      public Thread newThread(Runnable r) {
        return new Thread(r, "bid-collect-" + n.getAndIncrement());
      }
    });

@Async("mailExecutor")
public void sendMail(Long id) { ... }

@Bean("mailExecutor")
public ThreadPoolTaskExecutor mailExecutor() {
  ThreadPoolTaskExecutor e = new ThreadPoolTaskExecutor();
  e.setCorePoolSize(4); e.setMaxPoolSize(8);
  e.setQueueCapacity(200);
  e.setThreadNamePrefix("mail-");
  e.setRejectedExecutionHandler(new ThreadPoolExecutor.CallerRunsPolicy());
  e.initialize();
  return e;
}

rules.bad:
ThreadLocal<User> HOLDER = new ThreadLocal<>();
HOLDER.set(user);
// 请求结束未 remove → 线程复用时会读到上一个用户

rules.good:
ThreadLocal<User> HOLDER = new ThreadLocal<>();
try {
  HOLDER.set(user);
  doBusiness();
} finally {
  HOLDER.remove();   // 必须在 finally 中清理
}

rules.bad:
// 转账 A：先锁 from 再锁 to
synchronized (accountA) { synchronized (accountB) { ... } }
// 转账 B：先锁 to 再锁 from —— 与上面相反，并发时死锁

rules.good:
// 统一按业务主键大小排序后加锁
Long first  = Math.min(fromId, toId);
Long second = Math.max(fromId, toId);
lock(first);
lock(second);

rules.bad:
public synchronized void handle(Long id) {
  validate(id);            // 无需互斥
  remoteClient.call(id);   // 远程调用被锁住！
  counter++;
}

rules.good:
public void handle(Long id) {
  validate(id);
  remoteClient.call(id);
  counter.incrementAndGet();   // LongAdder，无锁原子操作
}
